/// <summary>
/// PaffH 30.05.22
/// </summary>
/// <returns>ItemName</returns>
display ItemNameDisplay ItemName()
{
    InventTable inventTable;
    select firstonly inventTable where inventTable.ItemId == this.ItemId;
    return inventTable.itemName();
}

/// <summary>
/// PaffH 30.05.22
/// </summary>
/// <returns>NDXProdIdentLabelName</returns>
display NDXProdIdentLabelName LabelName()
{
    return (select firstonly Name from NDXProdIdentLabel where NDXProdIdentLabel.Id == this.LabelId).Name;
}

/// <summary>
/// PaffH 17.08.22
/// </summary>
/// <param name = "_labelId">NDXProdIdentLabelId</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXProdIdentLabelItem</returns>
public static NDXProdIdentLabelItem find(NDXProdIdentLabelId _labelId, ItemId _itemId, boolean _forUpdate = true)
{
    NDXProdIdentLabelItem nDXProdIdentLabelItem;
    nDXProdIdentLabelItem.selectForUpdate(_forUpdate);
    select firstonly nDXProdIdentLabelItem
        where nDXProdIdentLabelItem.LabelId == _labelId
        && nDXProdIdentLabelItem.ItemId == _itemId;
    return nDXProdIdentLabelItem;
}

/// <summary>
/// PaffH 17.08.22
/// </summary>
/// <param name = "_labelId">NDXProdIdentLabelId</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXProdIdentLabelItem</returns>
public static NDXProdIdentLabelItem findOrCreate(NDXProdIdentLabelId _labelId, ItemId _itemId, boolean _doInsert = true)
{
    NDXProdIdentLabelItem nDXProdIdentLabelItem;
    nDXProdIdentLabelItem = NDXProdIdentLabelItem::find(_labelId, _itemId, true);
    if (!nDXProdIdentLabelItem)
    {
        nDXProdIdentLabelItem.LabelId = _labelId;
        nDXProdIdentLabelItem.ItemId = _itemId;
        if (_doInsert)
        {
            nDXProdIdentLabelItem.insert();
        }
    }
    return nDXProdIdentLabelItem;
}
